import csv
import io

def column_means(csv_text: str) -> dict[str, float]:
    result = {}
    csv_file = io.StringIO(csv_text)
    reader = csv.reader(csv_file)
    headers = next(reader)

    for header, row in zip(headers, reader):
        values = []
        for cell in row:
            if cell.strip() == '':
                continue
            try:
                values.append(float(cell))
            except ValueError:
                break
        else:
            if values:
                mean = sum(values) / len(values)
                result[header] = mean
    return result
